async function loadNextFavoriteGames(){st.nextGames={};st.nextGameErrors={};if(st.view!=='home'||!st.favorites.length)return;const today=new Date(`${todayKey()}T12:00:00Z`),cache=new Map(),limits={NFL:21,MLB:7},leagues=[...new Set(st.favorites.map(team=>team.league))],localHost=['localhost','127.0.0.1'].includes(location.hostname),workerBase=localHost?'http://127.0.0.1:8787':'https://skystation-sports-gateway.cgarrett4.workers.dev',gamesFor=async(league,date)=>{if(localHost)return providers[league].games(date);const raw=await endpoint(`${workerBase}/api/${league.toLowerCase()}/scores?date=${isoDate(date).replaceAll('-','')}`);return(raw.events||[]).map(event=>normalizeEspnGame(event,league))};for(const league of leagues){const limit=limits[league]||0;if(!providers[league]||!limit)continue;const pending=new Set(st.favorites.filter(team=>team.league===league).map(team=>team.id));for(let offset=1;offset<=limit&&pending.size;offset++){const date=new Date(today);date.setUTCDate(date.getUTCDate()+offset);const key=`${league}:${date.toISOString().slice(0,10)}`;if(!cache.has(key)){try{cache.set(key,await gamesFor(league,date))}catch(error){console.error(`[SkyStation Sports] ${league} upcoming games unavailable`,error);for(const teamId of pending)st.nextGameErrors[teamId]=true;cache.set(key,[])}}for(const teamId of [...pending]){const match=cache.get(key).find(g=>g.homeTeam?.id===teamId||g.awayTeam?.id===teamId);if(match){st.nextGames[teamId]=match;delete st.nextGameErrors[teamId];pending.delete(teamId)}}}}}
