const mlbPlayByPlayToggleSource=mlbPlayByPlay;mlbPlayByPlay=g=>mlbPlayByPlayToggleSource(g).replace(/<details class="mlb-inning-group"><summary>([\s\S]*?)<\/summary><div class="mlb-play-list">/g,'<div class="mlb-inning-group"><button type="button" class="mlb-inning-toggle" data-mlb-inning-toggle aria-expanded="false">$1</button><div class="mlb-play-list" hidden>').replace(/<\/div><\/details>/g,'</div></div>')
const mlbPlayByPlayOpenStateSource=mlbPlayByPlay;mlbPlayByPlay=g=>{const dialog=$('#dialog'),openInnings=new Set((dialog?.dataset.mlbOpenInnings||'').split('|').filter(Boolean));return mlbPlayByPlayOpenStateSource(g).replace(/data-mlb-inning-toggle aria-expanded="false">([^<]+)<\/button><div class="mlb-play-list" hidden>/g,(match,label)=>{const open=openInnings.has(label.trim());return`data-mlb-inning-toggle data-mlb-inning="${safe(label.trim())}" aria-expanded="${open}">${label}</button><div class="mlb-play-list"${open?'':' hidden'}>`})};
document.addEventListener('click',event=>{const tapped=event.target.closest('[data-mlb-inning-toggle]');if(!tapped)return;const dialog=$('#dialog'),key=tapped.dataset.mlbInning,button=[...(dialog?.querySelectorAll('[data-mlb-inning-toggle]')||[])].find(item=>item.dataset.mlbInning===key);if(!button)return;const plays=button.parentElement?.querySelector('.mlb-play-list');if(!plays)return;const open=button.getAttribute('aria-expanded')!=='true';button.setAttribute('aria-expanded',String(open));plays.hidden=!open;button.parentElement.classList.toggle('is-open',open);const openInnings=new Set((dialog.dataset.mlbOpenInnings||'').split('|').filter(Boolean));open?openInnings.add(key):openInnings.delete(key);dialog.dataset.mlbOpenInnings=[...openInnings].join('|')});
